import csv
import io


def parse_export_row(line):
    rows = list(csv.reader(io.StringIO(line), delimiter=";", strict=True))
    if not rows:
        return []
    if len(rows) != 1:
        raise ValueError("expected one CSV record")
    return [field for field in rows[0] if field]
